    url = f"{base_url}/place-an-order"
    payload = {
        "shipping_address": "123 Test St, Test City",
        "payment_method": "credit_card"
    }
    headers = {
        "Content-Type": "application/json"
    }
    try:
        response = requests.post(url, json=payload, headers=headers, timeout=30)
